import sys

def count_promising_substrings(s):
    n = len(s)
    count = 0
    for i in range(n):
        balance = 0
        for j in range(i, n):
            if s[j] == '-':
                balance += 1
            else:
                balance -= 1
            if balance <= 0:
                count += 1
    return count

def main():
    input_data = sys.stdin.readlines()
    t = int(input_data[0].strip())
    line_index = 1
    results = []
    for _ in range(t):
        n = int(input_data[line_index].strip())
        line_index += 1
        s = input_data[line_index].strip()
        line_index += 1
        results.append(count_promising_substrings(s))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
